from collections import deque
def bfs(graph, start):
    visited = {start}
    q = deque([start])
    order = []
    while q:
        node = q.popleft()
        order.append(node)
        for n in graph[node]:
            if n not in visited:
                visited.add(n)
                q.append(n)
    return order
